-- Migration 00074: Fix category French accents, Pheasant's Eye FR clinical fields, pellet pluralization,
-- TCM/MTC label artifacts in names/aliases/FAQs, remaining English common names in French titles,
-- curated regulator-backed White Willow drug interactions, and 1918 Dispensatory OCR typos.
-- Idempotent: all UPDATEs guard with IS DISTINCT FROM and INSERTs guard with WHERE NOT EXISTS.

-- 1. Fix French accents and natural naming on herb_categories (and flag affected bundles once)
WITH upd AS (UPDATE public.herb_categories SET description_fr = 'Plantes qui soutiennent le système nerveux', name_fr = 'Plante nervine' WHERE slug = 'nervine' AND (description_fr IS DISTINCT FROM 'Plantes qui soutiennent le système nerveux' OR name_fr IS DISTINCT FROM 'Plante nervine') RETURNING id) INSERT INTO public.herb_bundle_dirty (slug, queued_at) SELECT h.slug, now() FROM public.herbs h JOIN upd ON upd.id = h.category_id WHERE h.is_published ON CONFLICT (slug) DO UPDATE SET queued_at = excluded.queued_at;
WITH upd AS (UPDATE public.herb_categories SET description_fr = 'Plantes aux propriétés antalgiques', name_fr = 'Analgésique' WHERE slug = 'analgesic' AND (description_fr IS DISTINCT FROM 'Plantes aux propriétés antalgiques' OR name_fr IS DISTINCT FROM 'Analgésique') RETURNING id) INSERT INTO public.herb_bundle_dirty (slug, queued_at) SELECT h.slug, now() FROM public.herbs h JOIN upd ON upd.id = h.category_id WHERE h.is_published ON CONFLICT (slug) DO UPDATE SET queued_at = excluded.queued_at;
WITH upd AS (UPDATE public.herb_categories SET description_fr = 'Plantes qui soutiennent la digestion et la santé gastro-intestinale' WHERE slug = 'digestive' AND (description_fr IS DISTINCT FROM 'Plantes qui soutiennent la digestion et la santé gastro-intestinale') RETURNING id) INSERT INTO public.herb_bundle_dirty (slug, queued_at) SELECT h.slug, now() FROM public.herbs h JOIN upd ON upd.id = h.category_id WHERE h.is_published ON CONFLICT (slug) DO UPDATE SET queued_at = excluded.queued_at;
WITH upd AS (UPDATE public.herb_categories SET description_fr = 'Plantes qui soutiennent la santé des poumons et du système respiratoire' WHERE slug = 'respiratory' AND (description_fr IS DISTINCT FROM 'Plantes qui soutiennent la santé des poumons et du système respiratoire') RETURNING id) INSERT INTO public.herb_bundle_dirty (slug, queued_at) SELECT h.slug, now() FROM public.herbs h JOIN upd ON upd.id = h.category_id WHERE h.is_published ON CONFLICT (slug) DO UPDATE SET queued_at = excluded.queued_at;
WITH upd AS (UPDATE public.herb_categories SET description_fr = 'Plantes qui améliorent les fonctions cognitives et la mémoire' WHERE slug = 'nootropic' AND (description_fr IS DISTINCT FROM 'Plantes qui améliorent les fonctions cognitives et la mémoire') RETURNING id) INSERT INTO public.herb_bundle_dirty (slug, queued_at) SELECT h.slug, now() FROM public.herbs h JOIN upd ON upd.id = h.category_id WHERE h.is_published ON CONFLICT (slug) DO UPDATE SET queued_at = excluded.queued_at;
WITH upd AS (UPDATE public.herb_categories SET description_fr = 'Plantes qui soutiennent la santé du cœur et du système circulatoire' WHERE slug = 'cardiovascular' AND (description_fr IS DISTINCT FROM 'Plantes qui soutiennent la santé du cœur et du système circulatoire') RETURNING id) INSERT INTO public.herb_bundle_dirty (slug, queued_at) SELECT h.slug, now() FROM public.herbs h JOIN upd ON upd.id = h.category_id WHERE h.is_published ON CONFLICT (slug) DO UPDATE SET queued_at = excluded.queued_at;
WITH upd AS (UPDATE public.herb_categories SET description_fr = 'Plantes aux propriétés antibactériennes, antivirales et antifongiques' WHERE slug = 'antimicrobial' AND (description_fr IS DISTINCT FROM 'Plantes aux propriétés antibactériennes, antivirales et antifongiques') RETURNING id) INSERT INTO public.herb_bundle_dirty (slug, queued_at) SELECT h.slug, now() FROM public.herbs h JOIN upd ON upd.id = h.category_id WHERE h.is_published ON CONFLICT (slug) DO UPDATE SET queued_at = excluded.queued_at;
WITH upd AS (UPDATE public.herb_categories SET description_fr = 'Plantes qui soutiennent l''équilibre hormonal' WHERE slug = 'hormonal' AND (description_fr IS DISTINCT FROM 'Plantes qui soutiennent l''équilibre hormonal') RETURNING id) INSERT INTO public.herb_bundle_dirty (slug, queued_at) SELECT h.slug, now() FROM public.herbs h JOIN upd ON upd.id = h.category_id WHERE h.is_published ON CONFLICT (slug) DO UPDATE SET queued_at = excluded.queued_at;

-- 2. Repair Pheasant's Eye (Adonis vernalis) garbled French fields and FAQs
UPDATE public.herbs SET translations = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr,name}', to_jsonb('Adonis de printemps'::text), true), '{fr,description}', to_jsonb('L''adonis de printemps (Adonis vernalis) est une plante vivace de 30 à 40 cm aux tiges ramifiées et aux feuilles finement découpées, portant de grandes fleurs jaunes. Elle était traditionnellement utilisée comme stimulant cardiaque, agissant de façon comparable à la digitale et au strophanthus en renforçant les contractions du muscle cardiaque. Elle servait également en cas de fatigue cardiaque liée au surmenage, d''inflammation endocardique avec atteinte valvulaire et d''hydropisie d''origine cardiaque.'::text), true), '{fr,dosage_adult}', to_jsonb('Préparations standardisées uniquement — ne pas utiliser à domicile'::text), true), '{fr,traditional_uses}', '["Hydropisie et affections cardiaques", "Fatigue cardiaque liée au surmenage", "Inflammation endocardique avec valvulite", "Troubles cardiaques secondaires à la maladie de Bright", "Hydropisie d''origine cardiaque"]'::jsonb, true), '{fr,modern_uses}', '["Recherche sur les hétérosides cardiotoniques", "Préparations standardisées pour les troubles cardiaques légers en phytothérapie européenne"]'::jsonb, true), '{fr,contraindications}', '["Toute préparation non standardisée", "Grossesse", "Enfants", "Prise concomitante de digoxine ou de médicaments cardiaques"]'::jsonb, true), '{fr,preparation_notes}', to_jsonb('Utiliser uniquement des préparations pharmaceutiques standardisées ; marge thérapeutique étroite'::text), true) WHERE id = '8564577f-43fe-4470-b41b-fb428012b188' AND ((translations->'fr'->>'name') IS DISTINCT FROM 'Adonis de printemps' OR (translations->'fr'->>'description') IS DISTINCT FROM 'L''adonis de printemps (Adonis vernalis) est une plante vivace de 30 à 40 cm aux tiges ramifiées et aux feuilles finement découpées, portant de grandes fleurs jaunes. Elle était traditionnellement utilisée comme stimulant cardiaque, agissant de façon comparable à la digitale et au strophanthus en renforçant les contractions du muscle cardiaque. Elle servait également en cas de fatigue cardiaque liée au surmenage, d''inflammation endocardique avec atteinte valvulaire et d''hydropisie d''origine cardiaque.' OR (translations->'fr'->>'dosage_adult') IS DISTINCT FROM 'Préparations standardisées uniquement — ne pas utiliser à domicile' OR (translations->'fr'->'traditional_uses') IS DISTINCT FROM '["Hydropisie et affections cardiaques", "Fatigue cardiaque liée au surmenage", "Inflammation endocardique avec valvulite", "Troubles cardiaques secondaires à la maladie de Bright", "Hydropisie d''origine cardiaque"]'::jsonb OR (translations->'fr'->'modern_uses') IS DISTINCT FROM '["Recherche sur les hétérosides cardiotoniques", "Préparations standardisées pour les troubles cardiaques légers en phytothérapie européenne"]'::jsonb OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["Toute préparation non standardisée", "Grossesse", "Enfants", "Prise concomitante de digoxine ou de médicaments cardiaques"]'::jsonb OR (translations->'fr'->>'preparation_notes') IS DISTINCT FROM 'Utiliser uniquement des préparations pharmaceutiques standardisées ; marge thérapeutique étroite');
UPDATE public.herb_faqs SET translations = jsonb_set(jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr,question}', to_jsonb('Qui doit éviter Adonis de printemps ?'::text), true), '{fr,answer}', to_jsonb('Toute préparation non standardisée. Grossesse. Enfants. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche.'::text), true) WHERE id = '555c54b6-3806-40e2-ade8-2184d5c11e43' AND ((translations->'fr'->>'question') IS DISTINCT FROM 'Qui doit éviter Adonis de printemps ?' OR (translations->'fr'->>'answer') IS DISTINCT FROM 'Toute préparation non standardisée. Grossesse. Enfants. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche.');
UPDATE public.herb_faqs SET translations = jsonb_set(jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr,question}', to_jsonb('À quoi sert Adonis de printemps ?'::text), true), '{fr,answer}', to_jsonb('Hydropisie et affections cardiaques. Fatigue cardiaque liée au surmenage. Inflammation endocardique avec valvulite. (Relevé dans les monographies et les produits homologués : Health Canada LNHPD ; ITIS ; NCBI Taxonomy ; GBIF.)'::text), true) WHERE id = '9fa83bb4-c90f-4411-b43e-4704ebcaf671' AND ((translations->'fr'->>'question') IS DISTINCT FROM 'À quoi sert Adonis de printemps ?' OR (translations->'fr'->>'answer') IS DISTINCT FROM 'Hydropisie et affections cardiaques. Fatigue cardiaque liée au surmenage. Inflammation endocardique avec valvulite. (Relevé dans les monographies et les produits homologués : Health Canada LNHPD ; ITIS ; NCBI Taxonomy ; GBIF.)');
UPDATE public.herb_faqs SET translations = jsonb_set(jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr,question}', to_jsonb('Quelle posologie de Adonis de printemps est utilisée ?'::text), true), '{fr,answer}', to_jsonb('Préparations standardisées uniquement — ne pas utiliser à domicile. Il s''agit de la posologie figurant sur l''étiquette ou la monographie, et non d''une recommandation personnelle. (Health Canada LNHPD ; ITIS ; NCBI Taxonomy ; GBIF.)'::text), true) WHERE id = '89058fe7-c291-4d50-8a49-a2d34ad69903' AND ((translations->'fr'->>'question') IS DISTINCT FROM 'Quelle posologie de Adonis de printemps est utilisée ?' OR (translations->'fr'->>'answer') IS DISTINCT FROM 'Préparations standardisées uniquement — ne pas utiliser à domicile. Il s''agit de la posologie figurant sur l''étiquette ou la monographie, et non d''une recommandation personnelle. (Health Canada LNHPD ; ITIS ; NCBI Taxonomy ; GBIF.)');
UPDATE public.herb_faqs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr,question}', to_jsonb('D''où viennent ces informations sur Adonis de printemps ?'::text), true) WHERE id = 'e4f16867-2d61-4f71-ad39-fa077cce4cfe' AND ((translations->'fr'->>'question') IS DISTINCT FROM 'D''où viennent ces informations sur Adonis de printemps ?');

-- 3. Sync Milk Thistle French description opening with Chardon-Marie
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr,description}', to_jsonb('Le chardon-Marie (Silybum marianum) est utilisé depuis plus de 2 000 ans comme remède naturel contre les troubles du foie et de la vésicule biliaire. Son complexe d’ingrédients actifs, le silymarin, a fait l’objet d’études approfondies sur ses effets hépatoprotecteurs. Il constitue l’une des rares herbes disposant de solides preuves cliniques pour soutenir et protéger le foie.'::text), true) WHERE id = '523c5bfc-5570-4fdd-b840-ceb08fe07fff' AND (translations->'fr'->>'description') IS DISTINCT FROM 'Le chardon-Marie (Silybum marianum) est utilisé depuis plus de 2 000 ans comme remède naturel contre les troubles du foie et de la vésicule biliaire. Son complexe d’ingrédients actifs, le silymarin, a fait l’objet d’études approfondies sur ses effets hépatoprotecteurs. Il constitue l’une des rares herbes disposant de solides preuves cliniques pour soutenir et protéger le foie.';

