INSERT INTO public.drug_interactions (herb_id, drug_name, severity, description, mechanism, evidence_level, source, source_url, translations)
SELECT '45b9023a-2905-4235-ba9f-6bb71551f870'::uuid, 'Warfarin (Coumadin)', 'severe'::public.interaction_severity, 'Willow bark contains salicin, which is metabolized to salicylic acid and may increase the anticoagulant effect of warfarin, raising the risk of bleeding and elevated INR.', 'Salicylates inhibit platelet aggregation via cyclooxygenase blockade and can displace warfarin from plasma protein binding sites.', 'monograph', 'EMA HMPC — Salicis cortex (Willow bark)', 'https://www.ema.europa.eu/en/medicines/herbal/salicis-cortex', '{"fr": {"description": "L''écorce de saule blanc contient de la salicine, métabolisée en acide salicylique, ce qui peut amplifier l''effet anticoagulant de la warfarine et augmenter le risque d''hémorragie et d''élévation de l''INR.", "mechanism": "Les salicylates inhibent l''agrégation plaquettaire via le blocage des cyclo-oxygénases et peuvent déplacer la warfarine de ses sites de liaison aux protéines plasmatiques."}}'::jsonb
WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '45b9023a-2905-4235-ba9f-6bb71551f870'::uuid)
  AND NOT EXISTS (SELECT 1 FROM public.drug_interactions WHERE herb_id = '45b9023a-2905-4235-ba9f-6bb71551f870'::uuid AND drug_name = 'Warfarin (Coumadin)');
INSERT INTO public.drug_interactions (herb_id, drug_name, severity, description, mechanism, evidence_level, source, source_url, translations)
SELECT '45b9023a-2905-4235-ba9f-6bb71551f870'::uuid, 'Aspirin', 'moderate'::public.interaction_severity, 'Concurrent use of willow bark with aspirin may produce additive salicylate effects, increasing the risk of gastrointestinal irritation, ulceration, and bleeding.', 'Both white willow salicin derivatives and aspirin act through salicylic acid pathways that inhibit cyclooxygenase (COX) enzymes and reduce gastric mucosal protection.', 'monograph', 'EMA HMPC — Salicis cortex (Willow bark)', 'https://www.ema.europa.eu/en/medicines/herbal/salicis-cortex', '{"fr": {"description": "L''association d''écorce de saule blanc et d''aspirine peut entraîner un effet cumulatif des salicylates, augmentant le risque d''irritation gastrique, d''ulcération et de saignement.", "mechanism": "Les dérivés de la salicine du saule blanc et l''aspirine agissent tous deux via les voies de l''acide salicylique qui inhibent les enzymes cyclo-oxygénases (COX) et réduisent la protection de la muqueuse gastrique."}}'::jsonb
WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '45b9023a-2905-4235-ba9f-6bb71551f870'::uuid)
  AND NOT EXISTS (SELECT 1 FROM public.drug_interactions WHERE herb_id = '45b9023a-2905-4235-ba9f-6bb71551f870'::uuid AND drug_name = 'Aspirin');
INSERT INTO public.drug_interactions (herb_id, drug_name, severity, description, mechanism, evidence_level, source, source_url, translations)
SELECT '45b9023a-2905-4235-ba9f-6bb71551f870'::uuid, 'NSAIDs (Ibuprofen / Naproxen)', 'moderate'::public.interaction_severity, 'Combining willow bark with nonsteroidal anti-inflammatory drugs (NSAIDs) may increase the risk of gastrointestinal upset, mucosal ulceration, and bleeding.', 'Additive inhibition of prostaglandin synthesis and platelet function by willow-derived salicylates and NSAIDs compounds gastrointestinal and hemorrhagic risk.', 'monograph', 'EMA HMPC — Salicis cortex (Willow bark)', 'https://www.ema.europa.eu/en/medicines/herbal/salicis-cortex', '{"fr": {"description": "L''association d''écorce de saule blanc et d''anti-inflammatoires non stéroïdiens (AINS) peut augmenter le risque de troubles gastro-intestinaux, d''ulcérations et de saignements.", "mechanism": "L''inhibition additive de la synthèse des prostaglandines et de la fonction plaquettaire par les salicylates du saule et les AINS accroît les risques digestifs et hémorragiques."}}'::jsonb
WHERE EXISTS (SELECT 1 FROM public.herbs WHERE id = '45b9023a-2905-4235-ba9f-6bb71551f870'::uuid)
  AND NOT EXISTS (SELECT 1 FROM public.drug_interactions WHERE herb_id = '45b9023a-2905-4235-ba9f-6bb71551f870'::uuid AND drug_name = 'NSAIDs (Ibuprofen / Naproxen)');

-- 8. Fix verified 1918 US Dispensatory OCR typos in herb_monograph_sources.claims
UPDATE public.herb_monograph_sources SET claims = '[{"text": "\"The gum-resin obtained by incising the rhizomes and roots of Ferula Asafetida Linné and Ferula fetida Regel and of some other species of Ferula (Fam. Umbellifere), indigenous to Persia and adjacent countries, and yielding not less than 60 per cent. (or if powdered 50 per cent.) of aleohol-soluble constituents.\" U.S. \"Asafetida is an oleo-gum-resin obtained by incision from the root of Ferula fetida, Regel, and probably other species of Ferula.\" Br.", "section": "Description"}, {"text": "Ferula Asafetida was first described from actual observation by H. Falconer, who found it near Kashmir, and has long been successfully cultivated in the Edinburgh Botanical Gardens. It is distinguished by the greater height of the stem (6 to 10 feet), and by the numerous stem leaves furnished with wide sheathing petioles. The flowers are pale yellow, and the oval fruit thin, flat, foliaceous, and reddish brown, with pronounced vittz. It yields a milky juice having a powerful odor of asafetida.", "section": "Description"}, {"text": "Ferula fetida is a coarse umbelliferous plant, growing from five to seven feet high, with a large fleshy root, the crown of which is covered with coarse bristly fibers, and gives origin to large bipinnate radical leaves and a_ nearly naked stem which has only a few bipinnate leaves without wide sheathing petioles, and ends at the top in very numerous umbels. The flatwinged fruit have the vitte almost obsolete. This plant was first discovered in the sandy desert near the sea of Aral, by Lehmann, in 1844. Bunge found it in Persia about twenty years It would seem to be native all through Afghanistan.", "section": "Description"}, {"text": "It is possible that asafetida is obtained from various species of Ferula, yet the bulk of the drug probably comes from the official plants. Among the other plants yielding asafetida is Ferula Narthex Boiss. While this is disputed by Aitchison yet it appears that it is the source of the gum-resin obtained from certain portions of Afghanistan. Tschirch describes this plant with illustrations in S. W. P., 1910, p. 289. E. M. Holmes''s discussion of the asafetida plants (P. J., ser. iii, xix, 1888-1889) still remains one of our chief sources of information on the subject. (See also article on the sources of the fetid gumresins by James Small, P. J., 1913, vol. xe, p. 287.) Ferula Jeschkeana Vatke, which has been believed to be the source of asafetida, ac-", "section": "Description"}, {"text": "The asafetida plants are indigenous to Western Afghanistan and Eastern Persia. In 1687 the collection of asafetida was witnessed by Kaempfer, whose description of the method is very similar to that given by H. W. Bellew in 1872, and by J. E. T. Aitchison m 1884. Aceording to Aitchison, the high plaims of Afghanistan, two to four thousand feet above the sea, are arid and bare in winter, but in the early summer are covered with a thick growth of Ferula fetida, Dorema ammoniacum, and Ferula glabaniflua. The great cabbage-like heads of the asafetida plant, representing the primary stage of the flower heads covered over by the stipules of its leaves, are eaten raw by the natives as a sort of green. In June the asafetida is obtained. The root stock is first laid bare to the depth of a couple of inches, those plants only which have not reached their flower-bearing stage being selected. <A slice is then taken from the top of the root stock, which is immediately covered with twigs and clay, forming a sort of dome, with an opening towards the north, so that the sun cannot get at the exposed root. About five or six weeks later, a thick, gummy, not milky, reddish substance found upon the exposed surface of the root in more or less irregular lumps is scraped off with a piece of iron hoop or removed with a slice of the root and at once placed in a leather bag. The asafetida is conveyed to Herat, where it is adulterated with red clay before being sent into commerce. It is brought to this country directly from India, whither it is conveyed from Bushire and down the Indus, or it is shipped first to London and then to America. It sometimes comes in mats, but more frequently in cases, the former containing eighty or ninety pounds, the latter from two hundred to four hundred pounds.", "section": "Description"}]'::jsonb WHERE id = 'b50cf6e3-d25f-48b1-a564-fed6cb0cd9aa'::uuid AND claims IS DISTINCT FROM '[{"text": "\"The gum-resin obtained by incising the rhizomes and roots of Ferula Asafetida Linné and Ferula fetida Regel and of some other species of Ferula (Fam. Umbellifere), indigenous to Persia and adjacent countries, and yielding not less than 60 per cent. (or if powdered 50 per cent.) of aleohol-soluble constituents.\" U.S. \"Asafetida is an oleo-gum-resin obtained by incision from the root of Ferula fetida, Regel, and probably other species of Ferula.\" Br.", "section": "Description"}, {"text": "Ferula Asafetida was first described from actual observation by H. Falconer, who found it near Kashmir, and has long been successfully cultivated in the Edinburgh Botanical Gardens. It is distinguished by the greater height of the stem (6 to 10 feet), and by the numerous stem leaves furnished with wide sheathing petioles. The flowers are pale yellow, and the oval fruit thin, flat, foliaceous, and reddish brown, with pronounced vittz. It yields a milky juice having a powerful odor of asafetida.", "section": "Description"}, {"text": "Ferula fetida is a coarse umbelliferous plant, growing from five to seven feet high, with a large fleshy root, the crown of which is covered with coarse bristly fibers, and gives origin to large bipinnate radical leaves and a_ nearly naked stem which has only a few bipinnate leaves without wide sheathing petioles, and ends at the top in very numerous umbels. The flatwinged fruit have the vitte almost obsolete. This plant was first discovered in the sandy desert near the sea of Aral, by Lehmann, in 1844. Bunge found it in Persia about twenty years It would seem to be native all through Afghanistan.", "section": "Description"}, {"text": "It is possible that asafetida is obtained from various species of Ferula, yet the bulk of the drug probably comes from the official plants. Among the other plants yielding asafetida is Ferula Narthex Boiss. While this is disputed by Aitchison yet it appears that it is the source of the gum-resin obtained from certain portions of Afghanistan. Tschirch describes this plant with illustrations in S. W. P., 1910, p. 289. E. M. Holmes''s discussion of the asafetida plants (P. J., ser. iii, xix, 1888-1889) still remains one of our chief sources of information on the subject. (See also article on the sources of the fetid gumresins by James Small, P. J., 1913, vol. xe, p. 287.) Ferula Jeschkeana Vatke, which has been believed to be the source of asafetida, ac-", "section": "Description"}, {"text": "The asafetida plants are indigenous to Western Afghanistan and Eastern Persia. In 1687 the collection of asafetida was witnessed by Kaempfer, whose description of the method is very similar to that given by H. W. Bellew in 1872, and by J. E. T. Aitchison m 1884. Aceording to Aitchison, the high plaims of Afghanistan, two to four thousand feet above the sea, are arid and bare in winter, but in the early summer are covered with a thick growth of Ferula fetida, Dorema ammoniacum, and Ferula glabaniflua. The great cabbage-like heads of the asafetida plant, representing the primary stage of the flower heads covered over by the stipules of its leaves, are eaten raw by the natives as a sort of green. In June the asafetida is obtained. The root stock is first laid bare to the depth of a couple of inches, those plants only which have not reached their flower-bearing stage being selected. <A slice is then taken from the top of the root stock, which is immediately covered with twigs and clay, forming a sort of dome, with an opening towards the north, so that the sun cannot get at the exposed root. About five or six weeks later, a thick, gummy, not milky, reddish substance found upon the exposed surface of the root in more or less irregular lumps is scraped off with a piece of iron hoop or removed with a slice of the root and at once placed in a leather bag. The asafetida is conveyed to Herat, where it is adulterated with red clay before being sent into commerce. It is brought to this country directly from India, whither it is conveyed from Bushire and down the Indus, or it is shipped first to London and then to America. It sometimes comes in mats, but more frequently in cases, the former containing eighty or ninety pounds, the latter from two hundred to four hundred pounds.", "section": "Description"}]'::jsonb;
UPDATE public.herb_monograph_sources SET claims = '[{"text": "\"The dried seeds of Elettaria Cardamomum White et Maton (Fam. Zingiberacew), recently removed from the capsules.\" U. S. '''' Cardamom Seeds are the dried ripe seeds of Elettaria Cardamomum, Maton. The seeds should be kept in their pericarps and separated when required for use.\" Br.", "section": "Description"}, {"text": "The fruit of cardamom is official in most of the Pharmacopeias. The U. S$. Pharmacopeia in its definition confines cardamom to the seeds. In this it follows the British Pharmacopeeia which has always limited the drug to the seeds, but specifically states that the fruit should be kept intact) and the seeds separated when required for use. This step was probably a wise one as there has always been some econfusion by manufacturers as to whether the article designated as cardamom is a formula was restricted to the seeds or not. On the other hand the pericarp contains some oil and forms an excellent surface for the grinding of the seeds. Furthermore, the decorticated seeds are liable to adulteration with seed of wild cardamom and other foreign seeds which are not detected except upon careful examination.", "section": "Description"}, {"text": "The subject of cardamom has been involved in some confusion and uncertainty, both in its commercial and botanical relations. The name has been applied to the aromatic capsules of various Indian plants belonging to the family of Zingiberaceae. Three varieties have long been designated by the several titles of the lesser, middle, and larger - cardamomum minus, me-", "section": "Description"}, {"text": "Ceylon Cardamom. - This has been denominated variously cardamomum majus and cardamomum longum, and is sometimes termed in English commerce wild cardamom. it is the large cardamom of Guibourt. The fruit is a lanceolate-oblong, acutely triangular capsule, somewhat curved, about 3.5 em. long and 6 to 8 mm. broad, with flat and ribbed sides, tough and coriaceous, brownish or yellow ash-colored, having frequently at one end the long, cylindrical, three-lobed calyx, and at the other the fruit-stalk. It is three-locular, and contains angular, rugged, yellowish-red seeds, of a peculiar fragrant odor and spicy taste. Its effects are analogous to those of the official cardamom.", "section": "Description"}, {"text": "Round or Siam Cardamom. - tThis is probably the Apopuov of Dioscorides and _ the Amomi uva of Pliny, and is believed to be the fruit of Amomum cardamomum, Willd., growing in Sumatra, Java, and other Hast India islands. The capsules are usually smaller than a cherry, roundish or somewhat ovate, with three convex sides, more or less striated longitudinally, yellowish or ''brownish-white, and sometimes reddish, with brown, angular, cunelform, shrivelled seeds, which have a spicy camphorous flavor. They are sometimes, though rarely, met with connected in their native clusters, constituting the amomum racemosum, or amome en grappe, of the French. They are similar in medicinal properties to the official, but are seldom used except in the southern parts of Europe.", "section": "Description"}, {"text": "Java Cardamom. - tThe plant producing this variety is supposed to be the amomum maximum of Roxburgh, growing in Java and other Malay islands in the Kast. The capsules are oval, or oval-oblong, often somewhat ovate, from 1.5 to 3 em. long, and from 8 to 15 mm. broad, usually flattened on one side and convex on the other, sometimes curved, threevalved, and occasionally imperfectly threelobed, of a dirty grayish-brown color, and coarse", "section": "Description"}, {"text": "Madagascar Cardamom. - tThis is the Cardamomum majus of Geiger and some others, and is thought to be the fruit of Amomum angustifolium, of Sonnerat, growing in marshy grounds in Madagascar. The capsule is ovate, pointed, flattened on one side, striated, with a broad circular sear at the bottom, surrounded by an notched, corrugated margin. The seeds have an aromatic flavor similar to that of official cardamom.", "section": "Description"}]'::jsonb WHERE id = '158b9be7-846c-4571-83a1-dc494b742963'::uuid AND claims IS DISTINCT FROM '[{"text": "\"The dried seeds of Elettaria Cardamomum White et Maton (Fam. Zingiberacew), recently removed from the capsules.\" U. S. '''' Cardamom Seeds are the dried ripe seeds of Elettaria Cardamomum, Maton. The seeds should be kept in their pericarps and separated when required for use.\" Br.", "section": "Description"}, {"text": "The fruit of cardamom is official in most of the Pharmacopeias. The U. S$. Pharmacopeia in its definition confines cardamom to the seeds. In this it follows the British Pharmacopeeia which has always limited the drug to the seeds, but specifically states that the fruit should be kept intact) and the seeds separated when required for use. This step was probably a wise one as there has always been some econfusion by manufacturers as to whether the article designated as cardamom is a formula was restricted to the seeds or not. On the other hand the pericarp contains some oil and forms an excellent surface for the grinding of the seeds. Furthermore, the decorticated seeds are liable to adulteration with seed of wild cardamom and other foreign seeds which are not detected except upon careful examination.", "section": "Description"}, {"text": "The subject of cardamom has been involved in some confusion and uncertainty, both in its commercial and botanical relations. The name has been applied to the aromatic capsules of various Indian plants belonging to the family of Zingiberaceae. Three varieties have long been designated by the several titles of the lesser, middle, and larger - cardamomum minus, me-", "section": "Description"}, {"text": "Ceylon Cardamom. - This has been denominated variously cardamomum majus and cardamomum longum, and is sometimes termed in English commerce wild cardamom. it is the large cardamom of Guibourt. The fruit is a lanceolate-oblong, acutely triangular capsule, somewhat curved, about 3.5 em. long and 6 to 8 mm. broad, with flat and ribbed sides, tough and coriaceous, brownish or yellow ash-colored, having frequently at one end the long, cylindrical, three-lobed calyx, and at the other the fruit-stalk. It is three-locular, and contains angular, rugged, yellowish-red seeds, of a peculiar fragrant odor and spicy taste. Its effects are analogous to those of the official cardamom.", "section": "Description"}, {"text": "Round or Siam Cardamom. - tThis is probably the Apopuov of Dioscorides and _ the Amomi uva of Pliny, and is believed to be the fruit of Amomum cardamomum, Willd., growing in Sumatra, Java, and other Hast India islands. The capsules are usually smaller than a cherry, roundish or somewhat ovate, with three convex sides, more or less striated longitudinally, yellowish or ''brownish-white, and sometimes reddish, with brown, angular, cunelform, shrivelled seeds, which have a spicy camphorous flavor. They are sometimes, though rarely, met with connected in their native clusters, constituting the amomum racemosum, or amome en grappe, of the French. They are similar in medicinal properties to the official, but are seldom used except in the southern parts of Europe.", "section": "Description"}, {"text": "Java Cardamom. - tThe plant producing this variety is supposed to be the amomum maximum of Roxburgh, growing in Java and other Malay islands in the Kast. The capsules are oval, or oval-oblong, often somewhat ovate, from 1.5 to 3 em. long, and from 8 to 15 mm. broad, usually flattened on one side and convex on the other, sometimes curved, threevalved, and occasionally imperfectly threelobed, of a dirty grayish-brown color, and coarse", "section": "Description"}, {"text": "Madagascar Cardamom. - tThis is the Cardamomum majus of Geiger and some others, and is thought to be the fruit of Amomum angustifolium, of Sonnerat, growing in marshy grounds in Madagascar. The capsule is ovate, pointed, flattened on one side, striated, with a broad circular sear at the bottom, surrounded by an notched, corrugated margin. The seeds have an aromatic flavor similar to that of official cardamom.", "section": "Description"}]'::jsonb;
UPDATE public.herb_monograph_sources SET claims = '[{"text": "\"A balsam obtained from the wood and inner bark of Liquidambar orientalis Miller (Fam. Hamamelidacee).\" U. S. \"Prepared Storax is a viscid balsam obtained from the wounded trunk of Liquidambar orientalis, Mill., purified by solution in alcohol, filtration, and evaporation of the solvent.\" Br.", "section": "Description"}, {"text": "All species of the genus Liquidambar as well as those of a related genus, Altingia, yield storax, The product most valued, however, is that obtained from ZL. orientalis Miller.", "section": "Description"}, {"text": "The oriental sweet-gum (Liquidambar orientalis) is a tree from twenty to forty feet high. The palmate leaves have each of their divisions obseurely three-lobed, and are serrate, perfectly smooth, bright green and shining on the upper and pale on the under surface. The tree is a native of Asia Minor, in the southwestern parts of which it forms large forests. It yields the so-called liquid storax.", "section": "Description"}, {"text": "According to the researches of Moeller, storax is a pathological rather than a physiological product; when the young wood is injured secretion reservoirs are formed in which the storax is produced. (O. Z., 1.) In collecting the drug the outer bark is first heavily bruised. so as to injure the inner bark, and after a time the outer bark having been removed the inner bark is scraped off. According to Maltass, this inner bark is first pressed cold in horse-hair bags, after which hot water is thrown over the bags and they are again pressed. Lieutenant Campbell states that the inner bark is first boiled with water, and, a portion of the balsam which rises having been skimmed off, is then pressed so as to extract the remainder. The residuary bark, after expression, is dried in the sun, and em+ ployed in various parts of Turkey for fumiga~ tion. It is the drug known in commerce as Storax bark or Cortex Thymiamatis. (Hanbury, P. J., 1857, xvi, 463.) The balsam is sent in casks to Constantinople, Smyrna, and other ports of the Levant.", "section": "Description"}, {"text": "Several kinds of storax have been described. Another variety, formerly called styrax calamita, from the circumstance, it is supposed, that it was brought wrapped in the leaves of a kind of reed, consisted of dry and brittle masses, formed of yellowish agglutinated tears, in the interstices of which was a brown or reddish matter. The French call it storax amygdaloide", "section": "Description"}, {"text": "This and the preceding variety had a pleasant odor like that of vanilla. Neither of them, however, is now found in the markets. It is probable that one or both of these varieties may have been the product of Styrax officinale. A third variety, which was formerly seen in commeree, styrax calamita, was in brown or reddish-brown masses of various shapes, light, friable, yet possessing'' a certain degree of tenacity, and softening under the teeth. Upon exposure, it becomes covered upon the surface with a white efflorescence of styracin. It evidently consisted of sawdust, united with a portion of the balsam. As found in commerce, it was usually in the state of a coarse, soft, dark-colored powder, mingled with occasional light friable lumps of various sizes, and containing very little of the balsam. When good, it should yield, upon pressure between ''hot plates, a brown resinous fluid having the odor of storax. Hanbury states that some of this variety is prepared at Trieste, Venice, and Marseilles, by mixing the residue of the liquidambar bark remaining after expression, and reduced to coarse powder, with genuine liquid storax. (P.J., April, 1863.)", "section": "Description"}, {"text": "American Storax, Liqumdambar styraciflua, or Sweet Gum of our Southern States. - Its geographical range reaches into Mexico, and it yields a storax-like product in an abundance proportionate to the heat of the climate. A specimen from Guatemala is described by Fliickiger and Hanbury as a yellow, opaque resin, of honey-like consistence, becoming transparent, amber-colored, and brittle by exposure to the air, and having a rather terebinthinous balsamie odor and but little taste. Sometimes it oceurs as a thick golden-brown fluid. It contains cinnamic acid and stryacin. (A. J. P., 1874, p. 161.) It is soluble in alcohol, and has been gathered to a considerable extent in the United States for the preparation of chewing gum. The resins of Liquidambar formosana and L. altigiana are known in Eastern commerce. Malay storax is an aromatic resinous product obtained from the Altingia excelsa Noronha (L. altigiana Bl.) It is sometimes called rasamala resin and contains tannic acid besides a very minute amount of cinnamic and benzoie acids.", "section": "Description"}]'::jsonb WHERE id = 'f425cc9e-10fa-4158-ad51-7cb78ac22426'::uuid AND claims IS DISTINCT FROM '[{"text": "\"A balsam obtained from the wood and inner bark of Liquidambar orientalis Miller (Fam. Hamamelidacee).\" U. S. \"Prepared Storax is a viscid balsam obtained from the wounded trunk of Liquidambar orientalis, Mill., purified by solution in alcohol, filtration, and evaporation of the solvent.\" Br.", "section": "Description"}, {"text": "All species of the genus Liquidambar as well as those of a related genus, Altingia, yield storax, The product most valued, however, is that obtained from ZL. orientalis Miller.", "section": "Description"}, {"text": "The oriental sweet-gum (Liquidambar orientalis) is a tree from twenty to forty feet high. The palmate leaves have each of their divisions obseurely three-lobed, and are serrate, perfectly smooth, bright green and shining on the upper and pale on the under surface. The tree is a native of Asia Minor, in the southwestern parts of which it forms large forests. It yields the so-called liquid storax.", "section": "Description"}, {"text": "According to the researches of Moeller, storax is a pathological rather than a physiological product; when the young wood is injured secretion reservoirs are formed in which the storax is produced. (O. Z., 1.) In collecting the drug the outer bark is first heavily bruised. so as to injure the inner bark, and after a time the outer bark having been removed the inner bark is scraped off. According to Maltass, this inner bark is first pressed cold in horse-hair bags, after which hot water is thrown over the bags and they are again pressed. Lieutenant Campbell states that the inner bark is first boiled with water, and, a portion of the balsam which rises having been skimmed off, is then pressed so as to extract the remainder. The residuary bark, after expression, is dried in the sun, and em+ ployed in various parts of Turkey for fumiga~ tion. It is the drug known in commerce as Storax bark or Cortex Thymiamatis. (Hanbury, P. J., 1857, xvi, 463.) The balsam is sent in casks to Constantinople, Smyrna, and other ports of the Levant.", "section": "Description"}, {"text": "Several kinds of storax have been described. Another variety, formerly called styrax calamita, from the circumstance, it is supposed, that it was brought wrapped in the leaves of a kind of reed, consisted of dry and brittle masses, formed of yellowish agglutinated tears, in the interstices of which was a brown or reddish matter. The French call it storax amygdaloide", "section": "Description"}, {"text": "This and the preceding variety had a pleasant odor like that of vanilla. Neither of them, however, is now found in the markets. It is probable that one or both of these varieties may have been the product of Styrax officinale. A third variety, which was formerly seen in commeree, styrax calamita, was in brown or reddish-brown masses of various shapes, light, friable, yet possessing'' a certain degree of tenacity, and softening under the teeth. Upon exposure, it becomes covered upon the surface with a white efflorescence of styracin. It evidently consisted of sawdust, united with a portion of the balsam. As found in commerce, it was usually in the state of a coarse, soft, dark-colored powder, mingled with occasional light friable lumps of various sizes, and containing very little of the balsam. When good, it should yield, upon pressure between ''hot plates, a brown resinous fluid having the odor of storax. Hanbury states that some of this variety is prepared at Trieste, Venice, and Marseilles, by mixing the residue of the liquidambar bark remaining after expression, and reduced to coarse powder, with genuine liquid storax. (P.J., April, 1863.)", "section": "Description"}, {"text": "American Storax, Liqumdambar styraciflua, or Sweet Gum of our Southern States. - Its geographical range reaches into Mexico, and it yields a storax-like product in an abundance proportionate to the heat of the climate. A specimen from Guatemala is described by Fliickiger and Hanbury as a yellow, opaque resin, of honey-like consistence, becoming transparent, amber-colored, and brittle by exposure to the air, and having a rather terebinthinous balsamie odor and but little taste. Sometimes it oceurs as a thick golden-brown fluid. It contains cinnamic acid and stryacin. (A. J. P., 1874, p. 161.) It is soluble in alcohol, and has been gathered to a considerable extent in the United States for the preparation of chewing gum. The resins of Liquidambar formosana and L. altigiana are known in Eastern commerce. Malay storax is an aromatic resinous product obtained from the Altingia excelsa Noronha (L. altigiana Bl.) It is sometimes called rasamala resin and contains tannic acid besides a very minute amount of cinnamic and benzoie acids.", "section": "Description"}]'::jsonb;
UPDATE public.herb_monograph_sources SET claims = '[{"text": "\"The dried rhizomes of Zingiber officinale Roscoe (Fam, Zingiberaceae), the outer cortical layers of which are often either partially or completely removed. Preserve it in tightly closed containers, adding a few drops of chloroform or carbon tetrachloride, from time to time, to prevent attack by insects.\" U. S. \"Ginger is the scraped and dried rhizome of Zingiber officinale, Roscoe.\" Br,", "section": "Description"}, {"text": "There are about twenty species of the genus Zingiber, the commercial ginger being obtained from Zingiber officinale. According to Watt, this species is probably a native of tropical Asia, but is not known except in the cultivated state. It is now extensively cultivated in the tropical countries of both the Eastern and Western Hemispheres.", "section": "Description"}, {"text": "The ginger plant, Zingiber officinale, has a biennial or perennial, creeping rhizome, and an annual stem, which rises two or three feet in height, is solid, cylindrical, erect, and enclosed in an imbricated membranous sheathing. The leaves are lanceolate, acute, smooth, five or six inches long by about an inch in breadth, and stand alternately on the sheaths of the stem. The flower-stalk rises by the side of the stem from six inches to a foot, and, like it, is clothed with oval acuminate sheaths; but it is without leaves, '''' and terminates in an oval, obtuse, bracteal, imbricated spike. The flowers are of a dingy yellow color, and appear two or three at a time between the bracteal scales. The flowers have an aromatic odor, and the stems when bruised are slightly fragrant; but it is in the rhizome that the virtues of the plant reside. This is fit to be dug up when a year old. The rhizome of the ginger is lifted from the soil by a single thrust of the fork at the time when the stems of the plant turn white, before the rhizome has begun to get tough and fibrous. The root is scalded in boiling water and rapidly dried, when it constitutes the black or ordinary ginger of commerce.", "section": "Description"}, {"text": "In Martinique a ginger is said to be obtained by the cultivation of Zingiber Zerumbet Rose. The ginger of Siam is said to be produced by Alpinia Galanga, and is the same drug, therefore, as the Greater or Java Galanga Root. The large, ordinary, preserved ginger of China is, according to C. Ford (Kew Bulletin, 1891) also the product of A. Galanga. It is made by boiling young, tender, carefully selected and decorticated rhizomes in syrup. Preserved ginger from the West Indies is made from the official plant. According to Hartwich and Swanlund, the rhizome of the Zingiber Mioga, which is cultivated in China and Japan, has a taste less pungent than that of the official ginger, and distinctly recalling bergamot. In commerce the varieties of ginger are known by the place of their production. African and Cochin ginger on an average yield more resin and volatile oil than do the older varieties.", "section": "Description"}, {"text": "The recent root is from one to four inches long, somewhat flattened on its upper and under surface, knotty, obtusely and _ irregularly branched or lobed, externally of a light ash color with circular ruge, internally yellowish-white and fleshy. It sometimes begins to grow when kept in a damp atmosphere. The common or black ginger is of the same general shape, but has a dark ash-colored wrinkled epidermis, which, being removed in some places, exhibits patches of an almost black color, apparently the result of exposure. Beneath the epidermis is a brownish, resinous, almost horny cortical portion. The interior parenchyma is whitish, the cells being filled with starch. The powder is of a light yellowish-brown color. This variety is most extensively used. The Jamaica or white ginger is white or yellowish-white on the outside. The pieces are rounder and thinner, and afford when", "section": "Description"}]'::jsonb WHERE id = '41606fcf-1457-41bd-b282-f80c8fcc73ca'::uuid AND claims IS DISTINCT FROM '[{"text": "\"The dried rhizomes of Zingiber officinale Roscoe (Fam, Zingiberaceae), the outer cortical layers of which are often either partially or completely removed. Preserve it in tightly closed containers, adding a few drops of chloroform or carbon tetrachloride, from time to time, to prevent attack by insects.\" U. S. \"Ginger is the scraped and dried rhizome of Zingiber officinale, Roscoe.\" Br,", "section": "Description"}, {"text": "There are about twenty species of the genus Zingiber, the commercial ginger being obtained from Zingiber officinale. According to Watt, this species is probably a native of tropical Asia, but is not known except in the cultivated state. It is now extensively cultivated in the tropical countries of both the Eastern and Western Hemispheres.", "section": "Description"}, {"text": "The ginger plant, Zingiber officinale, has a biennial or perennial, creeping rhizome, and an annual stem, which rises two or three feet in height, is solid, cylindrical, erect, and enclosed in an imbricated membranous sheathing. The leaves are lanceolate, acute, smooth, five or six inches long by about an inch in breadth, and stand alternately on the sheaths of the stem. The flower-stalk rises by the side of the stem from six inches to a foot, and, like it, is clothed with oval acuminate sheaths; but it is without leaves, '''' and terminates in an oval, obtuse, bracteal, imbricated spike. The flowers are of a dingy yellow color, and appear two or three at a time between the bracteal scales. The flowers have an aromatic odor, and the stems when bruised are slightly fragrant; but it is in the rhizome that the virtues of the plant reside. This is fit to be dug up when a year old. The rhizome of the ginger is lifted from the soil by a single thrust of the fork at the time when the stems of the plant turn white, before the rhizome has begun to get tough and fibrous. The root is scalded in boiling water and rapidly dried, when it constitutes the black or ordinary ginger of commerce.", "section": "Description"}, {"text": "In Martinique a ginger is said to be obtained by the cultivation of Zingiber Zerumbet Rose. The ginger of Siam is said to be produced by Alpinia Galanga, and is the same drug, therefore, as the Greater or Java Galanga Root. The large, ordinary, preserved ginger of China is, according to C. Ford (Kew Bulletin, 1891) also the product of A. Galanga. It is made by boiling young, tender, carefully selected and decorticated rhizomes in syrup. Preserved ginger from the West Indies is made from the official plant. According to Hartwich and Swanlund, the rhizome of the Zingiber Mioga, which is cultivated in China and Japan, has a taste less pungent than that of the official ginger, and distinctly recalling bergamot. In commerce the varieties of ginger are known by the place of their production. African and Cochin ginger on an average yield more resin and volatile oil than do the older varieties.", "section": "Description"}, {"text": "The recent root is from one to four inches long, somewhat flattened on its upper and under surface, knotty, obtusely and _ irregularly branched or lobed, externally of a light ash color with circular ruge, internally yellowish-white and fleshy. It sometimes begins to grow when kept in a damp atmosphere. The common or black ginger is of the same general shape, but has a dark ash-colored wrinkled epidermis, which, being removed in some places, exhibits patches of an almost black color, apparently the result of exposure. Beneath the epidermis is a brownish, resinous, almost horny cortical portion. The interior parenchyma is whitish, the cells being filled with starch. The powder is of a light yellowish-brown color. This variety is most extensively used. The Jamaica or white ginger is white or yellowish-white on the outside. The pieces are rounder and thinner, and afford when", "section": "Description"}]'::jsonb;
